import numpy as np

def problem(x: np.ndarray) -> float:
    """
    Synthetic benchmark function designed to exhibit specific ELA features.

    This function combines a rotated ellipsoid, a sum of cosines, and a product of sines,
    to generate a landscape with controlled separability, multimodality, and ruggedness.

    Formula:
    f(x) = scale * (ellipsoid(x, rotation_matrix) + sum_cos(x) + prod_sin(x))
    """

    def ellipsoid(x, rotation_matrix):
        """Rotated Ellipsoid function."""
        z = np.dot(x, rotation_matrix)
        return np.sum(np.power(10, np.arange(x.shape[0]) / (x.shape[0] - 1)) * z**2)

    def sum_cos(x):
        """Sum of Cosines function."""
        return np.sum(np.cos(5 * x))

    def prod_sin(x):
        """Product of Sines function."""
        return np.prod(np.sin(x))

    # Create a random rotation matrix (deterministic)
    rng = np.random.RandomState(42) # Make it deterministic. remove if needed.

    theta = np.pi / 4  # Rotation angle
    rotation_matrix = np.array([[np.cos(theta), -np.sin(theta)], [np.sin(theta), np.cos(theta)]])


    scale = 0.1

    return scale * (ellipsoid(x, rotation_matrix) + sum_cos(x)  + prod_sin(x))
